<script setup lang="ts">
import FieldError from '../FleetAndDocuments/components/FieldError.vue';
import {computed,onBeforeUnmount,onMounted,ref,watch,useId} from 'vue';
import {all,paginated} from '../Administration/api';
import {labels} from '../TransportAndDispatch/presentation';
import {date,money,type Trip,type Currency,type Price} from './contracts';
const props=defineProps<{admin:boolean;locked:boolean;epoch:number;errors:Record<string,string[]>}>();
const emit=defineEmits<{command:[title:string,path:string,body:Record<string,unknown>];error:[error:unknown]}>();
const rows=ref<Trip[]>([]),customers=ref<{id:string;name:string}[]>([]),customer=ref(''),status=ref(''),pendingOnly=ref(false),search=ref(''),loading=ref(false),page=ref(1),last=ref(1),selected=ref<Trip|null>(null),checked=ref<string[]>([]),amount=ref(''),currency=ref<Currency>('CRC'),reason=ref(''),decisionReason=ref(''),invoiceReason=ref(''),proposalCorrection=ref(false),descriptions=ref<Record<string,string>>({});let generation=0;
const customerOptions=computed(()=>customers.value.filter(c=>c.name.toLocaleLowerCase('es').includes(search.value.toLocaleLowerCase('es'))));
const latestProposal=computed(()=>selected.value?.price_proposals.find(price=>!selected.value?.price_proposals.some(other=>other.supersedes_id===price.id))??null);
const selectedRows=computed(()=>rows.value.filter(row=>checked.value.includes(row.id))),group=computed(()=>selectedRows.value[0]);
async function load(target=1):Promise<void>{if(loading.value)return;const current=++generation;loading.value=true;try{const query=new URLSearchParams({page:String(target)});if(customer.value)query.set('customer_id',customer.value);if(status.value)query.set('execution_status',status.value);if(pendingOnly.value)query.set('pending_only','1');const result=await paginated<Trip>(`/billing/trips?${query}`);if(current!==generation)return;rows.value=result.data;page.value=result.meta.current_page;last.value=result.meta.last_page;checked.value=[];if(selected.value)selected.value=rows.value.find(row=>row.id===selected.value?.id)??null;}catch(e){if(current===generation)emit('error',e);}finally{if(current===generation)loading.value=false;}}
function inspect(row:Trip):void{selected.value=row;amount.value='';currency.value=row.approved_price?.currency??'CRC';reason.value='';decisionReason.value='';proposalCorrection.value=false;}
function choose(row:Trip,event:Event):void{const input=event.target as HTMLInputElement;if(input.checked){checked.value.push(row.id);descriptions.value[row.id]=`Transporte de ${row.product}`;}else checked.value=checked.value.filter(id=>id!==row.id);}
function compatible(row:Trip):boolean{return !!row.billing_eligibility&&(!group.value||(group.value.customer.id===row.customer.id&&group.value.approved_price?.currency===row.approved_price?.currency));}
function propose():void{if(!selected.value)return;emit('command',proposalCorrection.value?'Solicitar corrección auditable del importe':'Registrar importe acordado',`/billing/trips/${selected.value.id}/amounts`,{amount:amount.value,currency:currency.value,reason:reason.value,...(latestProposal.value?{supersedes_id:latestProposal.value.id}:{})});}
function decide(price:Price,decision:'approved'|'rejected'):void{emit('command',decision==='approved'?'Aprobar importe':'Rechazar importe',`/billing/amounts/${price.id}/decisions`,{decision,reason:decisionReason.value});}
function invoice():void{if(!group.value)return;emit('command','Crear factura administrativa interna','/billing/invoices',{customer_id:group.value.customer.id,items:selectedRows.value.map(row=>({trip_id:row.id,price_proposal_id:row.approved_price!.id,description:descriptions.value[row.id]})),reason:invoiceReason.value});}
watch(()=>props.epoch,()=>{amount.value='';reason.value='';decisionReason.value='';checked.value=[];void load(page.value);});onMounted(async()=>{const current=generation;try{const data=await all<{id:string;name:string}>('/transport/lookups/customers');if(current!==generation)return;customers.value=data;await load();}catch(e){if(current===generation)emit('error',e);}});onBeforeUnmount(()=>generation++);
const visible=computed(()=>rows.value);
const errorId=useId();
</script>
<template><section class="space-y-4"><h2 class="text-xl font-semibold">Importes autorizados y viajes</h2><form data-office-filter class="panel grid gap-4 md:grid-cols-3" @submit.prevent="load()"><label>Buscar cliente<input v-model="search" class="field" type="search" :disabled="locked"></label><label>Cliente<select aria-label="Cliente" v-model="customer" class="field" :disabled="locked"><option value="">Todos los clientes</option><option v-for="item in customerOptions" :key="item.id" :value="item.id">{{item.name}}</option></select></label><label>Estado de ejecución<select aria-label="Estado de ejecución" v-model="status" class="field" :disabled="locked"><option value="">Todos</option><option v-for="value in ['pending','in_progress','completed','cancelled']" :key="value" :value="value">{{labels[value]}}</option></select></label><label class="flex gap-2"><input v-model="pendingOnly" type="checkbox" :disabled="locked">Solo viajes pendientes de facturar</label><button class="btn-primary" :disabled="loading||locked">Consultar viajes</button></form><p v-if="loading" role="status">Consultando viajes…</p><div class="overflow-x-auto"><table class="data-table"><thead><tr><th>Facturar</th><th>Cliente / viaje</th><th>Producto</th><th>Estado</th><th>Importe aprobado</th><th>Acciones</th></tr></thead><tbody><tr v-for="row in visible" :key="row.id"><td><input type="checkbox" :aria-label="`Seleccionar viaje ${row.id}`" :checked="checked.includes(row.id)" :disabled="locked||!compatible(row)" @change="choose(row,$event)"></td><td>{{row.customer.name}}<br><span class="text-xs">{{row.id}}</span></td><td>{{row.product}}</td><td>{{labels[row.execution_status]}}<br>{{row.invoice_id?'Facturado':row.billing_eligibility?'Pendiente de facturar':'No facturable'}}</td><td>{{row.approved_price?money(row.approved_price.amount,row.approved_price.currency):'Sin importe aprobado'}}</td><td><button class="btn-secondary" :disabled="locked" @click="inspect(row)">Ver importe e historial</button></td></tr></tbody></table></div><p v-if="!loading&&!visible.length">No hay viajes para estos filtros.</p><div class="flex gap-3"><button class="btn-secondary" :disabled="loading||locked||page<=1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{last}}</span><button class="btn-secondary" :disabled="loading||locked||page>=last" @click="load(page+1)">Siguiente</button></div><form v-if="group" class="panel space-y-3" @submit.prevent="invoice"><h3 class="font-semibold">Crear factura administrativa interna</h3><p>{{checked.length}} viajes de {{group.customer.name}} · {{group.approved_price?.currency}}. Cada viaje se factura como un concepto de transporte, cantidad 1 y su importe aprobado. No se mezclan clientes ni monedas.</p><label v-for="row in selectedRows" :key="row.id">Concepto del viaje {{row.id}}<input v-model="descriptions[row.id]" class="field" required maxlength="2000" :disabled="locked"></label><label>Motivo de facturación<textarea v-model="invoiceReason" class="field" required maxlength="2000" :disabled="locked"/></label><button class="btn-primary" :disabled="locked">Crear factura administrativa</button></form><section v-if="selected" class="panel space-y-4"><div class="flex justify-between gap-3"><h3 class="font-semibold">Importe e historial · {{selected.customer.name}}</h3><button class="btn-secondary" :disabled="locked" @click="selected=null">Cerrar detalle</button></div><p class="text-xs">Viaje {{selected.id}}</p><p v-if="selected.invoice_id" class="notice-info">Viaje facturado. Los importes históricos no se pueden modificar. Correcciones posteriores a facturación requieren un procedimiento todavía no definido.</p><form v-else class="grid gap-3 md:grid-cols-2" @submit.prevent="propose"><label>Importe acordado<input v-model="amount" class="field" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,2})?" placeholder="0.00" required :disabled="locked" :aria-invalid="!!errors['amount']?.length" :aria-describedby="errors['amount']?.length ? `${errorId}-amount-error` : undefined"></label><FieldError :id="`${errorId}-amount-error`" :errors="errors['amount']"/><label>Moneda<select aria-label="Moneda" v-model="currency" class="field" :disabled="locked" :aria-invalid="!!errors['currency']?.length" :aria-describedby="errors['currency']?.length ? `${errorId}-currency-error` : undefined"><option>CRC</option><option>USD</option></select></label><FieldError :id="`${errorId}-currency-error`" :errors="errors['currency']"/><label v-if="latestProposal"><input v-model="proposalCorrection" type="checkbox" required :disabled="locked">Registrar nueva versión del importe (conserva todas las anteriores)</label><label class="md:col-span-2">Motivo del importe o corrección<textarea v-model="reason" class="field" maxlength="2000" required :disabled="locked"/></label><button class="btn-primary" :disabled="locked">Registrar importe para aprobación</button></form><p>Solo el administrador aprueba importes. Registrar una propuesta no habilita facturación.</p><label v-if="admin&&!selected.invoice_id">Motivo de decisión administrativa<input v-model="decisionReason" class="field" maxlength="2000" :disabled="locked"></label><ul class="space-y-3"><li v-for="price in selected.price_proposals" :key="price.id" class="border border-blue-200 rounded p-3"><p class="font-semibold">{{money(price.amount,price.currency)}} · {{price.decision?.decision==='approved'?'Aprobado':price.decision?.decision==='rejected'?'Rechazado':'Pendiente de aprobación'}}</p><p>{{price.reason}}</p><p class="text-sm">Registrado {{date(price.registered_at)}} · usuario {{price.requested_by_id}}</p><p v-if="price.decision" class="text-sm">{{price.decision.reason}} · {{date(price.decision.decided_at)}} · usuario {{price.decision.decided_by_id}}</p><div v-if="admin&&!price.decision&&!selected.invoice_id&&latestProposal?.id===price.id" class="flex gap-3 mt-2"><button class="btn-primary" :disabled="locked||!decisionReason.trim()" @click="decide(price,'approved')">Aprobar importe</button><button class="btn-secondary" :disabled="locked||!decisionReason.trim()" @click="decide(price,'rejected')">Rechazar importe</button></div></li></ul><p v-if="!selected.price_proposals.length">Sin propuestas registradas.</p></section></section></template>
